/**
 * Hosted eval cases. The control plane runs each `defineEval` case as its own
 * architecture v2 session: admission reserves the session's send for the
 * case, execution runs the case body there with every `t.send` a turn on
 * that session, and the verdict lands on the session log as
 * `eval.case.result`, which the control plane reads back.
 */
import { setTimeout as sleep } from "node:timers/promises";
import { describeError } from "./describe-error.js";
import { discoverEvals, runEvalCase } from "./eval-runner.js";
import { evalCaseOf } from "./http-control-plane-session.js";
import { RunSessionTimeoutError } from "./run-client.js";
import { buildTrajectory } from "./trajectory.js";
/** Under the 45-minute limit the host puts on one delivery. */
const CASE_DEADLINE_MS = 20 * 60_000;
/** Per tool-call input or output kept on the result; the session log keeps all of it. */
const MAX_TOOL_IO_CHARS = 8 * 1024;
export async function hostedEvalCatalog(projectRoot) {
    const { evals, config } = await discoverEvals(projectRoot);
    return {
        protocol: 1,
        cases: evals.map((e) => ({
            id: e.id,
            fileId: e.fileId,
            description: e.definition.description,
            tags: e.definition.tags,
        })),
        config: { maxConcurrency: config.maxConcurrency, timeoutMs: config.timeoutMs },
    };
}
/** One turn per captured send, or the whole case for an eval-case send. */
export function hostedSendStart(deps) {
    return async ({ args, message, options, sessionPublicId }) => {
        const evalCase = evalCaseOf(options);
        if (evalCase === undefined) {
            return args.send(message, options);
        }
        const done = runHostedEvalCase({
            ...deps,
            args,
            options,
            sessionId: sessionPublicId,
            evalCase,
        });
        return { id: sessionPublicId, waitForCompletion: () => done };
    };
}
/**
 * The delivery finishes once the verdict is recorded, whatever the verdict:
 * a failed case must not look like a failed delivery, which would retry it.
 */
async function runHostedEvalCase(input) {
    const startedAt = Date.now();
    const deadlineMs = input.caseDeadlineMs ?? CASE_DEADLINE_MS;
    const deadline = new AbortController();
    const cancel = new AbortController();
    const result = await Promise.race([
        runCase({ ...input, signal: cancel.signal }).catch((error) => failedResult(input.evalCase, describeError(error), startedAt)),
        sleep(deadlineMs, undefined, { signal: deadline.signal }).then(async () => {
            // The losing case body keeps running; it must not start turns after this verdict.
            cancel.abort();
            await input.engine.interrupt(input.sessionId);
            return failedResult(input.evalCase, `eval case exceeded ${deadlineMs / 60_000} minutes`, startedAt);
        }),
    ]).finally(() => deadline.abort());
    input.logger(`[bdk] eval case ${input.evalCase.caseId} (${input.evalCase.runId}): ${result.verdict ?? "failed"}`);
    await input.engine.recordEvalCaseResult(input.sessionId, resultEventData(input.evalCase, result));
    return { status: "finished" };
}
async function runCase(input) {
    const startedAt = Date.now();
    const { evals, config } = await discoverEvals(input.projectRoot);
    const discovered = evals.find((e) => e.id === input.evalCase.caseId);
    if (discovered === undefined) {
        return failedResult(input.evalCase, `No eval case ${JSON.stringify(input.evalCase.caseId)} in this release`, startedAt);
    }
    return runEvalCase(discovered, config, sessionTransport(input.engine, input.args, input.options), input.signal);
}
/** `t.send` as a turn on the admitted session, read back from its event log. */
function sessionTransport(engine, args, base) {
    return {
        async send(turn) {
            turn.signal?.throwIfAborted();
            const session = await args.send(turn.message, {
                ...base,
                workspaceDir: turn.options.workspaceDir,
                workspaceFiles: turn.options.workspaceFiles,
                cloud: turn.options.cloud,
            });
            if (turn.signal?.aborted) {
                await engine.interrupt(session.id);
                turn.signal.throwIfAborted();
            }
            const timer = new AbortController();
            const settled = await Promise.race([
                session.waitForCompletion().then(() => true),
                sleep(Math.min(turn.timeoutMs, CASE_DEADLINE_MS), false, { signal: timer.signal }),
            ]).finally(() => timer.abort());
            if (!settled) {
                await engine.interrupt(session.id);
                throw new RunSessionTimeoutError(`eval turn timed out after ${turn.timeoutMs}ms`, session.id, await engine.listEvents(session.id, turn.startIndex));
            }
            const events = await engine.listEvents(session.id, turn.startIndex);
            for (const event of events) {
                turn.onEvent?.(event);
            }
            const trajectory = buildTrajectory(events);
            return {
                sessionId: session.id,
                events,
                trajectory,
                ok: trajectory.ok,
                nextEventIndex: events.length === 0 ? undefined : events[events.length - 1].index + 1,
            };
        },
    };
}
function failedResult(ref, error, startedAt) {
    return {
        id: ref.caseId,
        path: "",
        ok: false,
        verdict: "failed",
        assertions: [],
        inputs: [],
        error,
        logs: [],
        metrics: {},
        durationMs: Date.now() - startedAt,
    };
}
function boundedIo(value) {
    if (value === undefined) {
        return undefined;
    }
    const json = JSON.stringify(value) ?? "";
    return json.length <= MAX_TOOL_IO_CHARS ? value : `${json.slice(0, MAX_TOOL_IO_CHARS)}…`;
}
function resultEventData(ref, result) {
    return {
        runId: ref.runId,
        caseId: ref.caseId,
        ok: result.ok,
        verdict: result.verdict ?? (result.ok ? "passed" : "failed"),
        skipReason: result.skipReason,
        assertions: result.assertions,
        durationMs: result.durationMs,
        error: result.error,
        logs: result.logs,
        metrics: result.metrics,
        metadata: result.metadata,
        inputs: result.inputs,
        finalText: result.finalText,
        tools: result.tools,
        toolCalls: result.toolCalls?.map((call) => ({
            toolName: call.toolName,
            args: boundedIo(call.args),
            output: boundedIo(call.output),
            isError: call.isError,
        })),
    };
}
